//! Lane sections that give one side of the road, with `singleSide`.
//!
//! `tests/data/single_side.xodr` is generated by `single_side.py`. See it for
//! the layout.

use xodr::{load_file_with_provenance, LaneId, Provenance, RoadNetwork, Warning};

fn fixture() -> (RoadNetwork, Provenance) {
    load_file_with_provenance("tests/data/single_side.xodr").unwrap()
}

fn lane(prov: &Provenance, road: &str, section: usize, od_id: i32) -> Option<LaneId> {
    prov.lanes
        .iter()
        .find(|p| p.road_id == road && p.section == section && p.od_id == od_id)
        .map(|p| p.lane)
}

fn ids(prov: &Provenance, road: &str, section: usize) -> Vec<i32> {
    let mut found: Vec<i32> = prov
        .lanes
        .iter()
        .filter(|p| p.road_id == road && p.section == section)
        .map(|p| p.od_id)
        .collect();
    found.sort();
    found
}

#[test]
fn a_section_that_gives_one_side_has_both_with_the_other_carried_on() {
    let (_, prov) = fixture();
    assert_eq!(ids(&prov, "1", 0), [-2, -1, 1, 2], "lane -3 has no width");
    assert_eq!(ids(&prov, "1", 1), [-2, -1, 1, 2], "right carried on");
    assert_eq!(ids(&prov, "1", 2), [-2, -1, 1, 2], "left carried on");
    assert_eq!(ids(&prov, "1", 3), [-2, -1, 1, 2]);
}

#[test]
fn a_carried_lane_is_as_wide_as_it_was_where_the_section_starts() {
    let (net, prov) = fixture();
    // Lane -1 widens from 3 m at 2 cm a metre. Where the second section
    // starts, at 50 m, it is 4 m, and it goes on to 5.4 m at 120 m.
    let carried = net.lane(lane(&prov, "1", 1, -1).unwrap()).unwrap();
    let length = carried.center.length();
    assert!(
        (carried.width_at(0.0) - 4.0).abs() < 0.01,
        "{}",
        carried.width_at(0.0)
    );
    assert!(
        (carried.width_at(length) - 5.4).abs() < 0.01,
        "{}",
        carried.width_at(length)
    );
    // The first section's own lane ends at 4 m, where the carried one starts.
    let own = net.lane(lane(&prov, "1", 0, -1).unwrap()).unwrap();
    assert!((own.width_at(own.center.length()) - 4.0).abs() < 0.01);
}

#[test]
fn a_carried_height_ramps_on_from_where_it_had_got_to() {
    let (_, prov) = fixture();
    let heights = |section| {
        let p = prov
            .lanes
            .iter()
            .find(|p| p.road_id == "1" && p.section == section && p.od_id == -1)
            .unwrap();
        (
            p.heights.first().copied().unwrap(),
            p.heights.last().copied().unwrap(),
        )
    };
    // The `<height>`s rise 0 to 0.2 m from 0 to 100 m, so at 50 m it is 0.1,
    // and it holds 0.2 m from 100 m on.
    let (first, last) = heights(1);
    assert!((first.inner - 0.1).abs() < 0.005, "{first:?}");
    assert!((last.inner - 0.2).abs() < 0.005, "{last:?}");
}

#[test]
fn a_carried_road_mark_starts_with_the_mark_in_force() {
    let (_, prov) = fixture();
    let mut marks: Vec<_> = prov
        .road_marks
        .iter()
        .filter(|m| m.road_id == "1" && m.od_lane_id == -1)
        .map(|m| (m.section, m.s, m.length))
        .collect();
    marks.sort_by(|a, b| a.1.total_cmp(&b.1));
    // The solid mark, from 0 m, is in force over the first section and to
    // 70 m. The broken one starts there, and runs on to the next section.
    assert_eq!(marks, [(0, 0.0, 50.0), (1, 50.0, 20.0), (1, 70.0, 50.0)]);
}

#[test]
fn links_run_from_a_side_to_the_copies_of_it_and_on_to_the_next_section_that_gave_it() {
    let (net, prov) = fixture();
    let successors = |section, od| -> Vec<(usize, i32)> {
        net.lane(lane(&prov, "1", section, od).unwrap())
            .unwrap()
            .successors
            .iter()
            .map(|s| {
                let p = prov.lanes.iter().find(|p| p.lane == *s).unwrap();
                (p.section, p.od_id)
            })
            .collect()
    };
    // Right lanes: given in section 0, carried through 1, given again in 2.
    assert_eq!(successors(0, -1), [(1, -1)]);
    assert_eq!(successors(1, -1), [(2, -1)]);
    assert_eq!(successors(2, -1), [(3, -1)]);
    // Left lanes run against +s, so what they lead on to lies behind them:
    // given in 0 and 1, carried through 2, given again in 3.
    assert_eq!(successors(3, 1), [(2, 1)]);
    assert_eq!(successors(2, 1), [(1, 1)]);
    assert_eq!(successors(1, 1), [(0, 1)]);
}

#[test]
fn a_carried_lane_is_not_a_dropped_lane_again() {
    let (_, prov) = fixture();
    let dropped: Vec<_> = prov
        .warnings
        .iter()
        .filter(|w| matches!(w, Warning::LaneDropped { road_id, .. } if road_id == "1"))
        .collect();
    assert_eq!(dropped.len(), 1, "lane -3 of section 0, once: {dropped:?}");
}

#[test]
fn the_center_lane_carries_on_through_a_side_only_section() {
    let (_, prov) = fixture();
    let sections: Vec<_> = prov
        .center_lanes
        .iter()
        .filter(|c| c.road_id == "1")
        .map(|c| c.section)
        .collect();
    assert_eq!(sections, [0, 1, 2, 3]);
}

#[test]
fn a_first_section_that_gives_one_side_has_nothing_on_the_other_until_one_does() {
    let (_, prov) = fixture();
    assert_eq!(ids(&prov, "2", 0), [-1]);
    assert_eq!(ids(&prov, "2", 1), [-1, 1], "the right lane carried on");
}

#[test]
fn without_singleside_a_section_with_one_side_has_only_that_side() {
    let (_, prov) = fixture();
    assert_eq!(ids(&prov, "3", 0), [-1]);
    assert_eq!(ids(&prov, "3", 1), [1], "false carries nothing on");
}

#[test]
fn a_mark_past_its_section_that_a_side_only_section_carries_on_is_not_dropped() {
    let (_, prov) = fixture();
    assert!(
        !prov
            .warnings
            .iter()
            .any(|w| matches!(w, Warning::RoadMarkDropped { .. })),
        "{:?}",
        prov.warnings
    );
}
